"use client";

import { useEffect, useState } from "react";
import {
  ArrowRight,
  ChevronDown,
  Loader2,
  Ship,
  Waves,
  AlertTriangle,
  CircleCheck,
  CircleHelp,
  BarChart3,
  Anchor,
  Route,
  SlidersHorizontal,
} from "lucide-react";

import {
  getDecisionMetadata,
  analyzeDecision,
  simulateScenario,
} from "../lib/api";

function formatNumber(value) {
  if (value === null || value === undefined || value === "") return "—";

  return new Intl.NumberFormat("en-IN").format(value);
}

function formatMoney(value) {
  if (value === null || value === undefined || value === "") return "—";

  return new Intl.NumberFormat("en-US", {
    maximumFractionDigits: 0,
  }).format(value);
}

function State({ value }) {
  if (!value) {
    return (
      <span className="state state-unknown">
        <CircleHelp size={14} />
        UNKNOWN
      </span>
    );
  }

  const normalized = String(value).toUpperCase();

  if (
    normalized.includes("FEASIBLE") ||
    normalized.includes("OBSERVED") ||
    normalized.includes("READY")
  ) {
    return (
      <span className="state state-good">
        <CircleCheck size={14} />
        {normalized}
      </span>
    );
  }

  if (
    normalized.includes("POTENTIAL") ||
    normalized.includes("WATCH") ||
    normalized.includes("REFERENCE")
  ) {
    return (
      <span className="state state-watch">
        <AlertTriangle size={14} />
        {normalized}
      </span>
    );
  }

  return (
    <span className="state state-unknown">
      <CircleHelp size={14} />
      {normalized}
    </span>
  );
}

function SelectField({
  label,
  value,
  options = [],
  onChange,
  disabled,
}) {
  return (
    <label className="input-field">
      <span>{label}</span>

      <div className="select-wrap">
        <select
          value={value || ""}
          onChange={(event) => onChange(event.target.value)}
          disabled={disabled}
        >
          <option value="">Select</option>

          {options.map((option) => {
            const value =
              typeof option === "string"
                ? option
                : option.id;

            const label =
              typeof option === "string"
                ? option
                : option.name;

            return (
              <option value={value} key={value}>
                {label}
              </option>
            );
          })}
        </select>

        <ChevronDown size={17} />
      </div>
    </label>
  );
}

export default function Home() {
  const [metadata, setMetadata] = useState(null);

  const [form, setForm] = useState({
    cargo: "",
    quantity_mt: "",
    origin_id: "",
    destination_id: "",
    delivery_window_days: "",
    contract_type: "spot",
  });

  const [decision, setDecision] = useState(null);
  const [scenario, setScenario] = useState(null);

  const [loadingMetadata, setLoadingMetadata] = useState(true);
  const [loadingDecision, setLoadingDecision] = useState(false);
  const [loadingScenario, setLoadingScenario] = useState(false);

  const [error, setError] = useState("");

  useEffect(() => {
    getDecisionMetadata()
      .then(setMetadata)
      .catch((err) => {
        setError(err.message);
      })
      .finally(() => {
        setLoadingMetadata(false);
      });
  }, []);

  function update(key, value) {
    setForm((current) => ({
      ...current,
      [key]: value,
    }));
  }

  async function runDecision(event) {
    event.preventDefault();

    setError("");
    setDecision(null);
    setScenario(null);
    setLoadingDecision(true);

    try {
      const result = await analyzeDecision({
        ...form,
        quantity_mt: Number(form.quantity_mt),
        delivery_window_days: Number(form.delivery_window_days),
      });

      setDecision(result);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoadingDecision(false);
    }
  }

  async function runScenario(waitingDays) {
    if (!decision) return;

    setLoadingScenario(true);
    setError("");

    try {
      const result = await simulateScenario({
        ...form,
        quantity_mt: Number(form.quantity_mt),
        delivery_window_days: Number(form.delivery_window_days),
        waiting_days: waitingDays,
      });

      setScenario(result);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoadingScenario(false);
    }
  }

  const origins = metadata?.origins || [];
  const destinations = metadata?.destinations || [];
  const cargoes = metadata?.cargoes || [];

  return (
    <main className="nereus-app">

      {/* =====================================================
          NAV
      ===================================================== */}

      <header className="site-nav">

        <div className="brand">
          <div className="brand-mark">
            N
          </div>

          <div>
            <strong>NEREUS</strong>
            <small>FREIGHT INTELLIGENCE</small>
          </div>
        </div>

        <nav>
          <a className="active">Decision</a>
          <a>Market</a>
          <a>Chartering</a>
          <a>Ports</a>
          <a>Scenarios</a>
        </nav>

        <div className="nav-status">
          <span />
          ENGINE
        </div>

      </header>


      {/* =====================================================
          HERO
      ===================================================== */}

      <section className="hero">

        <div className="hero-content">

          <div className="hero-kicker">
            MARITIME PROCUREMENT INTELLIGENCE
          </div>

          <h1>
            Make the next
            <br />
            voyage <em>count.</em>
          </h1>

          <p>
            Freight forecasting, vessel selection, port constraints
            and voyage economics in one decision workflow.
          </p>

        </div>

        <div className="hero-watermark">
          NEREUS
        </div>

      </section>


      {/* =====================================================
          DECISION INPUT
      ===================================================== */}

      <section className="decision-section">

        <div className="section-heading">

          <div>
            <span className="section-index">01</span>

            <h2>
              Build a procurement
              <br />
              scenario.
            </h2>
          </div>

          <p>
            Define the cargo movement. NEREUS will evaluate the
            market, route, vessel and operational constraints.
          </p>

        </div>

        <form
          className="decision-form"
          onSubmit={runDecision}
        >

          <SelectField
            label="Cargo"
            value={form.cargo}
            options={cargoes}
            onChange={(value) => update("cargo", value)}
            disabled={loadingMetadata}
          />

          <label className="input-field">
            <span>Quantity</span>

            <div className="quantity-input">
              <input
                type="number"
                min="1"
                value={form.quantity_mt}
                onChange={(event) =>
                  update("quantity_mt", event.target.value)
                }
                placeholder="60,000"
              />

              <b>MT</b>
            </div>
          </label>

          <SelectField
            label="Origin"
            value={form.origin_id}
            options={origins}
            onChange={(value) => update("origin_id", value)}
            disabled={loadingMetadata}
          />

          <SelectField
            label="Destination"
            value={form.destination_id}
            options={destinations}
            onChange={(value) => update("destination_id", value)}
            disabled={loadingMetadata}
          />

          <label className="input-field">
            <span>Delivery window</span>

            <div className="quantity-input">
              <input
                type="number"
                min="1"
                value={form.delivery_window_days}
                onChange={(event) =>
                  update(
                    "delivery_window_days",
                    event.target.value
                  )
                }
                placeholder="30"
              />

              <b>DAYS</b>
            </div>
          </label>

          <SelectField
            label="Contract strategy"
            value={form.contract_type}
            options={[
              { id: "spot", name: "Spot" },
              { id: "short_term", name: "Short term" },
              { id: "medium_term", name: "Medium term" },
            ]}
            onChange={(value) => update("contract_type", value)}
          />

          <button
            className="analyze-button"
            disabled={
              loadingDecision ||
              !form.cargo ||
              !form.quantity_mt ||
              !form.origin_id ||
              !form.destination_id ||
              !form.delivery_window_days
            }
          >
            {loadingDecision ? (
              <>
                <Loader2 className="spin" size={18} />
                ANALYZING
              </>
            ) : (
              <>
                ANALYZE VOYAGE
                <ArrowRight size={19} />
              </>
            )}
          </button>

        </form>

        {error && (
          <div className="error-box">
            <AlertTriangle size={18} />
            {error}
          </div>
        )}

      </section>


      {/* =====================================================
          RESULT
      ===================================================== */}

      {decision && (
        <>

          {/* ROUTE */}
          <section className="route-result">

            <div className="route-title">

              <span>ANALYSIS RESULT</span>

              <h2>
                {decision.scenario?.origin_name || "—"}
                <ArrowRight />
                {decision.scenario?.destination_name || "—"}
              </h2>

              <p>
                {decision.scenario?.cargo_name || "—"}
                {" · "}
                {formatNumber(decision.scenario?.quantity_mt)}
                {" MT"}
              </p>

            </div>

            <div className="route-stat">
              <span>ROUTE</span>
              <strong>
                {decision.route?.distance_nm
                  ? `${formatNumber(
                      Math.round(decision.route.distance_nm)
                    )} NM`
                  : "—"}
              </strong>
              <small>
                {decision.route?.status || "UNKNOWN"}
              </small>
            </div>

            <div className="route-stat">
              <span>SEA TIME</span>
              <strong>
                {decision.route?.voyage_days
                  ? `${decision.route.voyage_days} d`
                  : "—"}
              </strong>
              <small>CALCULATED</small>
            </div>

          </section>


          {/* =================================================
              FREIGHT + MARKET ENTRY
          ================================================= */}

          <section className="analysis-grid">

            <article className="analysis-card freight-card">

              <div className="card-top">
                <div>
                  <span>02 / MARKET</span>
                  <h3>Freight outlook</h3>
                </div>

                <BarChart3 />
              </div>

              <div className="big-value">
                {decision.market?.current_freight
                  ? `$${formatMoney(
                      decision.market.current_freight
                    )}`
                  : "—"}
              </div>

              <p>
                Current freight observation
              </p>

              <div className="forecast-placeholder">
                {decision.market?.forecast ? (
                  <div className="forecast-line">
                    Forecast available
                  </div>
                ) : (
                  <div className="empty-state">
                    Forecast data unavailable
                  </div>
                )}
              </div>

            </article>


            <article className="analysis-card entry-card">

              <div className="card-top">
                <div>
                  <span>03 / TIMING</span>
                  <h3>Market entry</h3>
                </div>

                <Route />
              </div>

              {decision.market_entry ? (
                <>
                  <div className="entry-result">
                    <strong>
                      {decision.market_entry.window || "—"}
                    </strong>

                    <span>
                      recommended entry window
                    </span>
                  </div>

                  <p>
                    {decision.market_entry.interpretation ||
                      "No interpretation returned."}
                  </p>
                </>
              ) : (
                <div className="empty-state large">
                  Market-entry analysis unavailable.
                </div>
              )}

            </article>

          </section>


          {/* =================================================
              VESSEL OPTIMIZATION
          ================================================= */}

          <section className="feature-section">

            <div className="feature-heading">

              <div>
                <span>04 / CHARTERING</span>

                <h2>
                  Choose the vessel
                  <br />
                  around the cargo.
                </h2>
              </div>

              <p>
                Feasibility is determined from vessel dimensions,
                cargo requirements and destination constraints.
              </p>

            </div>

            <div className="vessel-results">

              {(decision.vessels || []).map((vessel) => (
                <article
                  className="vessel-result"
                  key={vessel.id || vessel.class_name}
                >

                  <div className="vessel-icon">
                    <Ship size={28} />
                  </div>

                  <div className="vessel-main">
                    <span>VESSEL CLASS</span>

                    <h3>
                      {vessel.class_name || "—"}
                    </h3>

                    <p>
                      {vessel.dwt
                        ? `${formatNumber(vessel.dwt)} DWT`
                        : "—"}
                    </p>
                  </div>

                  <div className="vessel-constraint">
                    <span>DRAFT</span>

                    <strong>
                      {vessel.draft_m
                        ? `${vessel.draft_m} m`
                        : "—"}
                    </strong>
                  </div>

                  <div className="vessel-result-state">
                    <State value={vessel.status} />
                  </div>

                </article>
              ))}

              {!decision.vessels?.length && (
                <div className="empty-state large">
                  No vessel assessment returned.
                </div>
              )}

            </div>

          </section>


          {/* =================================================
              PORT INTELLIGENCE
          ================================================= */}

          <section className="feature-section dark-section">

            <div className="feature-heading">

              <div>
                <span>05 / PORTS</span>

                <h2>
                  The port decides
                  <br />
                  what the vessel can do.
                </h2>
              </div>

              <p>
                Loading and discharge constraints are evaluated
                separately from market conditions.
              </p>

            </div>

            <div className="port-analysis">

              <PortSide
                title="Loading port"
                data={decision.loading_port}
              />

              <div className="port-connector">
                <Waves size={30} />
              </div>

              <PortSide
                title="Discharge port"
                data={decision.discharge_port}
              />

            </div>

          </section>


          {/* =================================================
              COST
          ================================================= */}

          <section className="economics-section">

            <div className="feature-heading">

              <div>
                <span>06 / ECONOMICS</span>

                <h2>
                  What does the
                  <br />
                  voyage actually cost?
                </h2>
              </div>

              <p>
                Freight alone is not the decision. Voyage economics
                incorporate the available operating inputs.
              </p>

            </div>

            <div className="cost-grid">

              <Cost
                label="Freight"
                value={decision.cost?.freight}
              />

              <Cost
                label="Fuel"
                value={decision.cost?.fuel}
              />

              <Cost
                label="Port"
                value={decision.cost?.port}
              />

              <Cost
                label="Waiting"
                value={decision.cost?.waiting}
              />

              <Cost
                label="Positioning"
                value={decision.cost?.positioning}
              />

              <Cost
                label="Total"
                value={decision.cost?.total}
                total
              />

            </div>

          </section>


          {/* =================================================
              WHAT IF
          ================================================= */}

          <section className="scenario-section">

            <div className="feature-heading">

              <div>
                <span>07 / WHAT-IF LAB</span>

                <h2>
                  What happens
                  <br />
                  if the vessel waits?
                </h2>
              </div>

              <p>
                Test operational uncertainty without changing
                the underlying scenario.
              </p>

            </div>

            <div className="scenario-controls">

              {[0, 2, 5, 10].map((days) => (
                <button
                  key={days}
                  onClick={() => runScenario(days)}
                  disabled={loadingScenario}
                >
                  <strong>{days}</strong>
                  <span>
                    {days === 1 ? "day" : "days"}
                  </span>
                </button>
              ))}

            </div>

            {scenario && (
              <div className="scenario-result">

                <div>
                  <span>DELIVERY</span>
                  <strong>
                    {scenario.delivery_days
                      ? `${scenario.delivery_days} days`
                      : "—"}
                  </strong>
                </div>

                <div>
                  <span>WAITING</span>
                  <strong>
                    {scenario.waiting_days ?? "—"} days
                  </strong>
                </div>

                <div>
                  <span>COST</span>
                  <strong>
                    {scenario.total_cost
                      ? `$${formatMoney(
                          scenario.total_cost
                        )}`
                      : "—"}
                  </strong>
                </div>

                <div>
                  <span>SLACK</span>
                  <strong>
                    {scenario.slack_days ?? "—"}
                  </strong>
                </div>

              </div>
            )}

          </section>


          {/* =================================================
              RISK
          ================================================= */}

          <section className="risk-section">

            <div>
              <span>08 / RISK</span>

              <h2>
                Know what could
                <br />
                change the decision.
              </h2>
            </div>

            <div className="risk-list">

              {(decision.risks || []).map((risk, index) => (
                <div className="risk-row" key={index}>

                  <strong>
                    {risk.name || "Risk"}
                  </strong>

                  <span>
                    {risk.value || "—"}
                  </span>

                  <State value={risk.status} />

                </div>
              ))}

              {!decision.risks?.length && (
                <div className="empty-state">
                  No risk assessment returned.
                </div>
              )}

            </div>

          </section>

        </>
      )}


      {!decision && !loadingDecision && (
        <section className="empty-home">

          <Anchor size={34} />

          <h2>
            Your voyage analysis
            <br />
            will appear here.
          </h2>

          <p>
            Enter a procurement scenario above to evaluate
            freight, market timing, vessel feasibility,
            port constraints, cost and operational risk.
          </p>

        </section>
      )}

    </main>
  );
}


function PortSide({ title, data }) {
  return (
    <div className="port-side">

      <span>{title}</span>

      <h3>
        {data?.name || "—"}
      </h3>

      <div className="port-constraints">

        <Constraint
          label="LOA"
          value={data?.loa}
        />

        <Constraint
          label="Beam"
          value={data?.beam}
        />

        <Constraint
          label="Draft"
          value={data?.draft}
        />

        <Constraint
          label="Handling"
          value={data?.handling}
        />

      </div>

    </div>
  );
}


function Constraint({ label, value }) {
  return (
    <div>
      <span>{label}</span>
      <strong>{value ?? "—"}</strong>
    </div>
  );
}


function Cost({ label, value, total }) {
  return (
    <div className={total ? "cost total" : "cost"}>

      <span>{label}</span>

      <strong>
        {value === null ||
        value === undefined ||
        value === ""
          ? "—"
          : `$${formatMoney(value)}`}
      </strong>

    </div>
  );
}
